head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getMaxLength]<br/>Body Column 정보를 사용하여 특정 Column 의 maxLength 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine(한 Row 가 여러 줄로 표시)이어도 모든 Column 은 고유의 인덱스값을 가지며, columnInfo 인덱스로 해당 Column 의 maxLength 속성값을 반환합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = name(인덱스0, maxLength 10) / birth(인덱스1, maxLength 미설정)
//  - 2줄 = memo(인덱스2, maxLength 20) / etc(인덱스3, maxLength 미설정)
//  - Row 가 MultiLine 이어도 name~etc 는 각각 고유 인덱스(0~3) 를 가짐
//  - 2줄에 배치된 memo 도 고유 인덱스 2 -> getMaxLength(2) 로 memo 의 maxLength(20) 반환
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 name(고유 인덱스 0, text maxLength=10)/birth(1, text maxLength 미설정), 2줄 memo(2, text maxLength=20)/etc(3, text maxLength 미설정). memo 는 2줄에 있어도 고유 인덱스 2.\n[절차] columnInfo(고유 인덱스) 선택 후 실행 -> getMaxLength(인덱스) 로 해당 Column 의 maxLength 반환.\n[확인] getColumnID(인덱스) 매핑으로 MultiLine 이어도 인덱스 2 가 2줄 memo 컬럼(maxLength=20)을 정확히 지목함을 확인. 인덱스 0 은 name(10) 반환."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (MultiLine 2줄 : name/birth(1줄), memo/etc(2줄))
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="etc" name="etc" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "HONG", "birth": "19850315", "memo": "메모0", "etc": "비고0" },
        { "name": "KIM",  "birth": "19900720", "memo": "메모1", "etc": "비고1" },
        { "name": "LEE",  "birth": "19880103", "memo": "메모2", "etc": "비고2" }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList: "data:dlt_bind"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : name(0, text maxLength=10) / birth(1, text)
    //  - 2줄 : memo(2, text maxLength=20) / etc(3, text)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getMaxLength MultiLine 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="이름(maxLength 10)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="생년월일"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="memo(maxLength 20, 2줄)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="비고"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : name (text, maxLength=10, 1줄)
    strTarget += '<w2:column width="280" inputType="text" id="name" dataList="name" maxLength="10"></w2:column>';
    // index 1 : birth (text, maxLength 미설정, 1줄)
    strTarget += '<w2:column width="*" inputType="text" id="birth" dataList="birth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : memo (text, maxLength=20, 2줄) -> MultiLine 고유 인덱스 2
    strTarget += '<w2:column width="280" inputType="text" id="memo" dataList="memo" maxLength="20"></w2:column>';
    // index 3 : etc (text, maxLength 미설정, 2줄)
    strTarget += '<w2:column width="*" inputType="text" id="etc" dataList="etc"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getMaxLength 실행 : par_columnInfo(고유 인덱스) 로 호출
//  - MultiLine(2줄) 이어도 각 컬럼은 고유 인덱스로 지목됨 -> getColumnID(인덱스) 매핑으로 확인
//  - getMaxLength(인덱스) 로 해당 Column 의 maxLength 속성값 반환
scwin.btn_getMaxLength_onclick = function () {
    // columnInfo 는 MultiLine 상의 고유 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());

    // 인덱스 -> 컬럼 ID 매핑 (MultiLine 이어도 고유 인덱스가 정확한 컬럼을 지목함을 확인)
    let colID = target1.getColumnID(colIndex);

    // 고유 인덱스로 maxLength 반환
    let maxLen = target1.getMaxLength(colIndex);

    let out = "getMaxLength(" + colIndex + ") = " + maxLen + " [고유 인덱스 " + colIndex + " -> getColumnID : " + colID + "]";
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
